/**
 * Source-plugin discovery contract (virtual:openan-plugins).
 *
 * The virtual module is generated by the test-time twin of the Portal's
 * `openan-plugin-discovery` Vite plugin: it scans plugins/ for folders with a
 * plugin.manifest.js and honors plugins/plugin-overrides.json. These tests pin
 * both the discovery RULES and the current repository state.
 */
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import discovered from 'virtual:openan-plugins';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pluginsDir = path.join(repoRoot, 'plugins');

/** All source-plugin folder names present on disk (manifest required). */
function sourcePluginsOnDisk() {
    return fs.readdirSync(pluginsDir, { withFileTypes: true })
        .filter((d) => d.isDirectory())
        .map((d) => d.name)
        .filter((name) => fs.existsSync(path.join(pluginsDir, name, 'plugin.manifest.js')))
        .sort();
}

describe('virtual:openan-plugins discovery', () => {
    it('discovers exactly the source plugins enabled by plugin-overrides.json', () => {
        const overrides = JSON.parse(fs.readFileSync(path.join(pluginsDir, 'plugin-overrides.json'), 'utf-8'));
        const expected = sourcePluginsOnDisk()
            .filter((name) => overrides[name]?.enabled !== false);

        expect(discovered.plugins.map((p) => p.id).sort()).toEqual(expected);
        // Current repository state: exactly the two enabled source plugins.
        expect(expected).toEqual(['execution-center', 'skill-center']);
    });

    it('excludes the orchestration-center source plugin (disabled: superseded by its bundle)', () => {
        const discoveredIds = discovered.plugins.map((p) => p.id);
        expect(discoveredIds).not.toContain('orchestration-center');
    });

    it('exposes every discovered entry as enabled with a resolvable manifest loader whose id matches', async () => {
        expect(discovered.plugins.length).toBeGreaterThan(0);
        for (const entry of discovered.plugins) {
            expect(entry.enabled).toBe(true);
            expect(typeof entry.manifest).toBe('function');
            const mod = await entry.manifest();
            const manifest = mod.default ?? mod;
            expect(manifest.id).toBe(entry.id);
        }
    });
});
